$ErrorActionPreference='Stop';
$files=@('E:\WebAIBridge\app\worker.js','E:\WebAIBridge\app\server.js','E:\WebAIBridge\app\supervisor-watchdog.js');
$out=@();
foreach($f in $files){
 if(Test-Path $f){
   $patterns=@('requireHighMode','High mode is not confirmed','managed_assignment_high_race','enforceHighMode','highModeStrategy','Высокий|High','Средний|Medium');
   $matches=@();
   foreach($p in $patterns){
     $m=Select-String -Path $f -Pattern $p -SimpleMatch -CaseSensitive:$false | Select-Object -First 12 LineNumber,Line;
     if($m){$matches += [pscustomobject]@{pattern=$p;items=@($m)}}
   }
   $blob=(git hash-object $f 2>$null);
   $sha=(Get-FileHash -Algorithm SHA256 $f).Hash;
   $out += [pscustomobject]@{path=$f;gitBlob=$blob;sha256=$sha;matches=@($matches)}
 }
}
$procs=Get-CimInstance Win32_Process | Where-Object { $_.CommandLine -match 'E:\\WebAIBridge\\app|17448' -and $_.CommandLine -notmatch 'E:\\manhwa' } | Select-Object ProcessId,ParentProcessId,Name,CommandLine;
[pscustomobject]@{files=@($out);processes=@($procs)} | ConvertTo-Json -Depth 7 -Compress
